const text = $json.output?.[0]?.content?.[0]?.text || '';

const cleaned = text
  .replace(/```json\s*/i, '')
  .replace(/```\s*/g, '')
  .trim();

const queries = JSON.parse(cleaned);

return queries.map(query => ({
  json: {
    query
  }
}));

const docs = $json.docs || [];
const search = docs.map(d => {
  const uri = (d.resource && d.resource[0]) || '';
  const title = decodeURIComponent(uri.split('/').pop() || '').replace(/_/g, ' ');
  const comment = (d.comment && d.comment[0]) || '';
  return {
    title: title,
    snippet: comment.replace(/<\/?B>/g, ''),
    pageid: Math.abs(uri.split('').reduce((a, c) => a + c.charCodeAt(0), 0)),
    timestamp: ''
  };
}).filter(x => x.title);
return [{ json: { query: { search: search } } }];

const results = $input.first().json.query.search || [];

return results.map(item => ({
  json: {
    title: item.title,
    url: `https://en.wikipedia.org/wiki/${encodeURIComponent(item.title.replace(/ /g, '_'))}`,
    snippet: item.snippet
      ? item.snippet.replace(/<[^>]*>/g, '')
      : '',
    pageId: item.pageid,
    timestamp: item.timestamp
  }
}));

const docs = $json.docs || [];
let extract = '';
if (docs.length) {
  const d = docs[0];
  const parts = [];
  if (d.label && d.label[0]) parts.push(d.label[0].replace(/<\/?B>/g, ''));
  if (d.comment && d.comment[0]) parts.push(d.comment[0].replace(/<\/?B>/g, ''));
  if (d.category) parts.push('Categories: ' + d.category.map(c => (c.label && c.label[0]) || '').filter(Boolean).join(', '));
  extract = parts.join('. ');
}
return [{ json: { query: { pages: { p: { extract: extract } } } } }];

const response = $json;

const pages = response.query?.pages || {};
const page = Object.values(pages)[0];

const original = $('Process Search Results').item.json;

return [
  {
    json: {
      title: original.title,
      url: original.url,
      snippet: original.snippet,
      pageId: original.pageId,
      content: page?.extract || ''
    }
  }
];

const report = $json.output?.[0]?.content?.[0]?.text || '';

if (!report) {
  throw new Error('AI research report is empty.');
}

function extractSection(text, heading, nextHeadings = []) {
  const escapedHeading = heading.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  let pattern = `###\\s*${escapedHeading}\\s*\\n([\\s\\S]*?)`;

  if (nextHeadings.length > 0) {
    const nextPattern = nextHeadings
      .map(h => `###\\s*${h.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`)
      .join('|');

    pattern += `(?=\\n(?:${nextPattern})|$)`;
  } else {
    pattern += '$';
  }

  const match = text.match(new RegExp(pattern, 'i'));

  return match ? match[1].trim() : '';
}

const headings = [
  'Executive Summary',
  'Key Findings',
  'Important Facts',
  'Benefits',
  'Challenges',
  'Latest Trends',
  'Future Outlook',
  'Source References'
];

return [
  {
    json: {
      topic: $('Merge Research Data').first().json.title,
      report: report.trim(),
      executiveSummary: extractSection(report, 'Executive Summary', headings.slice(1)),
      keyFindings: extractSection(report, 'Key Findings', headings.slice(2)),
      importantFacts: extractSection(report, 'Important Facts', headings.slice(3)),
      benefits: extractSection(report, 'Benefits', headings.slice(4)),
      challenges: extractSection(report, 'Challenges', headings.slice(5)),
      latestTrends: extractSection(report, 'Latest Trends', headings.slice(6)),
      futureOutlook: extractSection(report, 'Future Outlook', headings.slice(7)),
      sourceReferences: extractSection(report, 'Source References'),
      generatedAt: new Date().toISOString()
    }
  }
];

const fs = require('fs');
const p = 'C:/Users/Administrator/.easyclaw/workspace/n8n-lesson-crew/state/19710-data/reports.json';
let rows = [];
try { rows = JSON.parse(fs.readFileSync(p, 'utf8')); } catch (e) {}
const row = { Date: $json.generatedAt, Topic: $json.topic, Result: $json.report, Summary: $json.executiveSummary };
const i = rows.findIndex(r => r.Topic === row.Topic);
if (i >= 0) rows[i] = row; else rows.push(row);
fs.writeFileSync(p, JSON.stringify(rows, null, 2));
return [{ json: $json }];

